def classify_email(subject: str, sender: str) -> str:
    spam_keywords = ['urgent wire transfer', 'lottery winner', 'claim your prize']
    normalized = subject.lower()

    for keyword in spam_keywords:
        if keyword in normalized:
            return 'SPAM'
    return 'INBOX'

print(classify_email('You are the lottery winner!', 'promo@prize.org'))
